m = re.search(r"weimojiejing:\s*\[", t)
assert m
start = m.end()
end = t.find('\n  ],', start)
insert = ''
for i, item in enumerate(items):
    comma = ',' if i < len(items) - 1 else ''
    insert += "    '" + item + "'" + comma + "\n"
t = t[:end] + '\n' + insert + t[end:]

open('lib/translations.ts', 'w', encoding='utf-8').write(t)
print('维摩诘经第二批补', len(items), '段')
